// Runnable demo: assignment within a group and across groups.
package com.bank.group.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ConsumerGroupDemo {
    private static final Logger log = Logger.getLogger(ConsumerGroupDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Topic topic = new Topic("transactions", 6); // 6 partitions
        topic.produce("SAV2001", new TxnRecord("T1", "SAV2001", new BigDecimal("50000")));
        topic.produce("CUR3001", new TxnRecord("T2", "CUR3001", new BigDecimal("8000")));

        // MAIN group: 3 consumers share 6 partitions (2 each)
        Group main = new Group("txn-main", topic);
        main.addConsumers("inst-A", "inst-B", "inst-C");
        main.rebalanceAndShow();

        // One instance crashes -> coordinator reassigns its partitions
        log.warning(() -> "inst-B crashed — triggering rebalance");
        main.removeConsumer("inst-B");
        main.rebalanceAndShow();

        // FRAUD group: independent, gets ALL 6 partitions (2 consumers => 3 each)
        Group fraud = new Group("fraud", topic);
        fraud.addConsumers("fraud-1", "fraud-2");
        fraud.rebalanceAndShow();
    }
}

