class TxnRecord {
    private final String id, accountId;
    private final BigDecimal amount;
    TxnRecord(String id, String accountId, BigDecimal amount) {
            this.id = id;
            this.accountId = accountId
            this.amount = amount;
    }
    @Override public String toString() { return id + " " + accountId + " " + amount; }
}

// ─── Would be in Topic.java ───
class Topic {
    private static final Logger log = Logger.getLogger(Topic.class.getName());
    private final String name;
    private final int partitions;
    private final Map<Integer, List<TxnRecord>> data = new TreeMap<>();
    Topic(String name, int partitions) {
        this.name = name; this.partitions = partitions;
        for (int i = 0; i < partitions; i++) data.put(i, new ArrayList<>());
    }
    int partitionCount() { return partitions; }
    void produce(String key, TxnRecord r) {
        int p = Math.floorMod(key.hashCode(), partitions);
        data.get(p).add(r);
        log.info(() -> "PRODUCE " + name + " key=" + key + " -> partition " + p);
    }
}

// ─── Would be in Coordinator.java ───
class Coordinator {
    // Round-robin: spread partitions one by one across consumers
    Map<String, List<Integer>> assign(List<String> consumers, int partitions) {
        Map<String, List<Integer>> map = new LinkedHashMap<>();
        for (String c : consumers) map.put(c, new ArrayList<>());
        if (consumers.isEmpty()) return map;
        for (int p = 0; p < partitions; p++) {
            String owner = consumers.get(p % consumers.size());
            map.get(owner).add(p);
        }
        return map;
    }
}

// ─── Would be in Group.java ───
class Group {
    private static final Logger log = Logger.getLogger(Group.class.getName());
    private final String groupId;
    private final Topic topic;
    private final Coordinator coordinator = new Coordinator();
    private final List<String> consumers = new ArrayList<>();
        Group(String groupId, Topic topic) { this.groupId = groupId;
        this.topic = topic; }
    void addConsumers(String... ids) { consumers.addAll(Arrays.asList(ids)); }
    void removeConsumer(String id) { consumers.remove(id); }
    void rebalanceAndShow() {
        Map<String, List<Integer>> a = coordinator.assign(consumers, topic.partitionCount());
        log.info(() -> "[" + groupId + "] REBALANCE complete");
        a.forEach((c, parts) ->
            log.info(() -> "[" + groupId + "] " + c + " owns partitions " + parts));
    }
}

